questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: [lat0, N/S, d1 (1 north, -1 south), dphi, lon0, E/W, d2 (1 east, -1 west), dlam]. Signed: north and east positive. The wrong-operation node applies on every entry (added when the ship moves towards the equator, subtracted when it moves away). Source: original. */
Q: [[5,"N",-1,12,170,"E",1,25],[3,"S",1,9,20,"W",1,35],[12,"N",1,15,8,"E",-1,30],[20,"S",-1,18,150,"W",-1,40],[8,"S",1,20,35,"E",1,40],[15,"N",-1,10,160,"E",1,15],[2,"N",-1,14,12,"W",1,20],[25,"S",1,7,100,"E",-1,45],[6,"S",1,30,165,"W",-1,30],[10,"N",-1,6,5,"E",-1,25]];
ix: 1+rand(10);
E: Q[ix];
lat0: E[1]; ns0: E[2]; d1: E[3]; dphi: E[4]; lon0: E[5]; ew0: E[6]; d2: E[7]; dlam: E[8];
s0: if ns0="N" then lat0 else -lat0;
s1: s0+d1*dphi;
g0: if ew0="E" then lon0 else -lon0;
graw: g0+d2*dlam;
g1: if graw>180 then graw-360 else (if graw<=-180 then graw+360 else graw);
lat1: abs(s1); ns1: if s1>0 then "N" else "S"; lon1: abs(g1); ew1: if g1>0 then "E" else "W";
nsw: if ns1="N" then "S" else "N"; eww: if ew1="E" then "W" else "E";
xeq: is(s0*s1<0); away: is(s0*d1>0);
wrA: if away then abs(lat0-dphi) else lat0+dphi;
x180: is(abs(graw)>180); xgr: is(g0*graw<0);
unred: abs(graw);
n0: is(ns0="N"); e0: is(ew0="E"); n1: is(ns1="N"); e1: is(ew1="E");
opt2: [["N", is(ns1="N"), "N"], ["S", is(ns1="S"), "S"]];
opt4: [["E", is(ew1="E"), "E"], ["W", is(ew1="W"), "W"]];

feedbackvariables.text:
c1: is(ans1=lat1 and ans2=ns1);
z1: is(ans1=lat1);
w1: is(ans1=wrA);
ys: if ans2="N" then ans1 else -ans1;
yd: ys-s0;

c2: is(ans3=lon1 and ans4=ew1);
big: is(ans3>180);
z2: is(ans3=lon1);
yg: if ans4="E" then ans3 else -ans3;
yd: mod(yg-g0+180,360)-180;
